        cout << "Failed to open file!" << endl;
        return 1;
    }

    // 读取文件内容并存储到字符串向量中
    string line;
    while (getline(file, line)) {
        fileContent.push_back(line);
    }

    // 遍历字符串向量中的每一行，并计算单词出现次数
