            string line2 = fileContent[j];
            if (line2.find(word) != string::npos && line2.find(word) != 0) {
                count++;
            }
        }
        wordCount[word] = count;
    }

    // 输出统计结果
    cout << "Word Count:" << endl;
    for (auto& entry : wordCount) {
